-- lyric previews from LRCLIB (scripts/fetch-previews.mjs). Safe to re-run; never overwrites an existing preview.
alter table public.songs add column if not exists preview text check (char_length(preview) <= 200);

update public.songs set preview = v.preview from (values
('em khong the|tien tien', 'Em vẫn nhớ như in những lần xa nhau Chỉ cần quay lưng chớp mắt Em đã nhớ anh da diết thật thà mong Sẽ gần nhau thêm đôi chút Hãy cho em biết điều này sắp kết thúc Anh có buồn không'),
('ve voi em di|tien tien', 'La-la-la-la, la-la-la-la, la-la-la-la La-la-la-la, la-la-la-la, la-la-la-la Anh đừng mãi miết bay như mây trời Anh đừng tha thiết rơi rụng như lá khô kia Anh đừng như sóng xô mải m'),
('noel biet yeu|tien tien', 'Merry Christmas Merry Merry Merry Điều ước bây giờ ngay lúc này chỉ có hai điều First that is you Hai cũng là điều mới nói ra Trong lòng bươm bướm bay vờn Sống như người trên mây F'),
('nguoi yeu xin so|tien tien', 'Người không hay nhắn tin Còn lại mình hay nghĩ nhiều Sợ người kia hết yêu Bỗng dưng mình hóa phiền, mình hóa điên Người thờ ơ không dỗ dành Còn mình lại hay đành hanh Nếu em là anh'),
('mot nguoi nhe nhang hon|tien tien', 'Đã mất một thời gian khá lâu Để quên anh Đôi khi giật mình những thói quen Lòng chợt nhớ nhung về những ngày xưa Ta từng yêu thế nào Môi hôn anh ngọt ngào Người ta vẫn nói nếu còn '),
('mot giac mo|kimmese', 'Khi màn đêm rơi nhẹ rơi Ánh trăng đó đang xé lòng ai Thành những vết thương buông lơi Những vết thương buông lơi Trôi qua những niềm đau Cuối cơn gió ai khiến em vội vã Nhìn thời g'),
('dung tron trong phong|kimmese', 'Một mình em ôm cô đơn nấp trong căn phòng Bao lâu tay chưa vẽ nắng xanh Một mình em đem ưu tư giấu trong ngăn bàn Dòng chữ kia từng nét bút gửi đến ai? (eh-eh-eh-eh) Kìa phố cơn mư'),
('tren cao nhin xuong|kimmese', 'Đứng trên đây, thử nhìn xem những thứ dưới này Ta nhìn thấy, sự cuồng điên đã giữ ta lại Cầm chắc microphone, cầm chắc microphone, nhịp tim ta rung mạnh! Cầm chắc microphone, thấy '),
('dung nhac may em|kimmese', 'You''ve been wantin'' somebody Like somebody you used to love All the problems you gotta deal with Don''t matter enough Take you far away from loneliness And yes, some love Some love,'),
('cho em mot ngay|kimmese', 'Yeah Cho em một ngày, một ngày thôi Một ngày không khắc khoải chờ đợi Một ngày không mưa rơi, mưa rơi buồn tủi Một ngày không tê tái heo may Và ta Mang cho em những nhành hoa Hoa m'),
('nang|bao uyen', 'Eh eh yeah Yeah yeah yeah yeah Ta gặp nhau nơi phố quen Và ánh mắt của anh làm em xao xuyến mất rồi Đêm nằm nghe sao nhớ ai Không biết bây giờ anh làm chi, bối rối rất nhiều Nắng c'),
('luc em can anh dang o dau|bao uyen', 'Đừng hỏi em giờ đang thế nào Đừng vờ quan tâm em sống sao Khi chính anh là người đã muốn Bỏ mặc em trong ngàn vụn vỡ Đừng bắt em làm bạn với người Từng yêu nhưng nay đã cách rời Hã'),
('roi nguoi thuong cung hoa nguoi dung|bao uyen', 'Những tin nhắn anh xem vẫn chưa trả lời Cuộc gọi nhỡ vẫn còn chưa đáp hồi Có lẽ mỗi người còn bận lo lắng cho riêng mình Giờ đây chỉ còn một thói quen chưa kịp quên Đã lâu lắm anh '),
('tet xa|bao uyen', 'Tích tắc đồng hồ đang trôi Tết đến còn vài ngày thôi Lũ bạn đã kéo nhau đi về rồi Phố xá những ngày năm cuối hối hả dòng người ngược xuôi Bất chợt chỉ muốn gọi về mẹ thôi Để thấy l'),
('roi em se on thoi|bao uyen', 'Liệu anh còn nhớ Những ngày đầu mình có nhau Anh đã hứa rằng Sẽ yêu em đến mãi sau Lá thu chưa thay màu Lời hẹn hứa đã phai quá mau Tình yêu dẫu đậm sâu Chỉ đẹp khi ban đầu Tình yê'),
('buon khong the buong|bao uyen', 'Người ta nay đã bước đi Sao em vẫn ở lại Tự ôm nỗi buồn Không biết nói cho ai Rồi khi cơn mưa rơi xuống Hai dòng lệ cứ tuôn Buồn nào đau hơn nỗi buồn không thể buông Trời đã ngớt m'),
('mua he nam ay|bao uyen', 'Đứng dưới mái hiên nhà giữa trưa hè Mắt chạm nhau thoáng bối rối yêu từ phút ban đầu Đứng dưới tán cây rợp mát khung trời Khẽ chạm môi mà trái tim bỗng dưng đập liên hồi. Rồi thời '),
('yeu nhu chien tranh|bao uyen', 'Anh ấy là của tôi Nhưng đôi khi tôi gây nhiều rắc rối Anh ấy tuyệt lắm Anh cho tôi tất cả những gì tôi muốn He''s my sugar daddy Trước khi thấy tôi Anh đã từng là một người rất cô đ'),
('nhung cau hoi khi say|bao uyen', 'Giữa màn đêm tối tâm hồn mong được cứu rỗi một mình rượu nồng nhấp môi Không một câu nói muốn rời xa là xa thôi chẳng buồn một lời với tôi Thật sự muốn biết anh liệu có từng nuối t'),
('lien khuc: tet trong tam hon|bao uyen', 'Lại một năm mới Tết đến tiếng pháo báo đông đi qua Để cho muôn nơi hoan ca mang Tết vui về mọi nhà Từng lời ca, từng lời ca Từng lời ca, từng lời ca Vang lên như rộn rã Rồi ngàn đi'),
('bai ca dat phuong nam|phuong my chi', 'Bài ca Đất Phương Nam Nhắn ai đi về miền đất phương Nam Trời xanh mây trắng, soi dòng Cửu Long Giang Mênh mông rừng tràm, bạt ngàn dừa xanh. Tiếng chang đước đong đưa, nhớ người xư'),
('vu tru co anh|phuong my chi', 'Nô nức đông vui (vui-vui-vui), vua mở hội trên Kinh đô (lá-la-là) Nhung gấm xinh tươi, người ta đang hân hoan cùng dạo phố Xe pháo như nêm, nhưng chỉ mình em không vui (ooh-whoo-oo'),
('thuong ve mien trung|phuong my chi', 'Đã bao lâu rồi không về miền Trung thăm người em Nắng mưa đêm ngày cách trở, giờ xa xôi đôi đường Người ơi có về miền quê hương Thùy Dương Nước chảy còn vương bao niềm thương cho n'),
('ech ngoai day gieng|phuong my chi', 'Mình thiệt thà chân quê Đi ra nước ngoài làm người ta mê Đồng bằng rồi sông núi Em ca mấy bài làm bà con vui Mình là mình thanh niên Bên trên đáy giếng em không làm biếng Việc gì m'),
('den khuya|phuong my chi', 'Không biết đêm nay vì sao tôi buồn Buồn vì trời mưa hay bão trong tim Đã mấy thu qua tôi vẫn đi tìm Để rồi buồn ơi nghe tiếng mưa đêm. Khi bước chân đi lần trong cuộc đời Lời mẹ hi'),
('nha con thuong em ma|phuong my chi', 'Về nhà em ơi, về nhà Gặp lại người thân vốn xa lạ Người mà vốn dĩ người nhà Chỉ là, từ lâu cách xa Về nhà em ơi, về nhà Nguồn cội mẹ cha với ông bà Một mình bôn ba vất vả Về nhà, c'),
('nhung ngoi sao xa xoi|phuong my chi', 'Nắng chiếu trên đồi ánh lên như gọi loài hoa trên đá Đóa hoa chưa đặt tên vẫn ngát hương cho dù gần xa Tóc ngắn, môi cười, mắt nâu như mặt trời giữa rừng sâu Trong khó khăn, chị em'),
('nguoi con gai nam nghe bien hat|phuong my chi', 'Có một người con gái Nắng hồng lên đôi má Ngồi hát câu gì? Tóc cài hoa lê trắng Giữa mùa trăng năm ấy Lùa gió trong tay (Hah-ah-ah-ah-ah) Khúc hát ngân nga bao xa đường về nhà (Hah'),
('dat anh choi hoi|phuong my chi', 'Người ơi, nói em nghe về miền trời thênh thang Dắt em qua ngàn vết thương hoang tàn Thả trôi đi, mình phó theo thời gian (hah-ah) Trào dâng sóng xô nghiêng vệt nắng tô ngoan hiền V'),
('hinh anh nguoi em khong doi|phuong my chi', 'Ngày nào em đến Áo em màu trinh Áo xinh là xinh Áo em trong trời buồn Là gió là bướm là hoa Là mây chiều tà Ngày nào em đến Nón em cầm tay Nón em màu mây Nón em sao thẹn thùng Kề t'),
('ngay tet que em|phuong my chi', 'Tết, Tết, Tết, Tết đến rồi Tết, Tết, Tết, Tết đến rồi Tết, Tết, Tết, Tết, Tết đến rồi Tết đến trong tim mọi người Mừng ngày Tết trên khắp quê tôi Ngàn hoa thơm khoe sắc xinh tươi Đ'),
('hen em kiep sau|phuong my chi', 'Hỏi trời cao hỡi tình là chi vừa gặp nhau đã vội biệt ly Nhìn anh bước theo người khuất dần em chỉ lặng thinh Tưởng rằng may mắn tìm được nhau nào ngờ đâu đứt đoạn dây tơ Trách kiế'),
('lieu yeu dao to|phuong my chi', 'Gió sương, dương liễu vươn mình trong ngày gió sương Em vốn kiên cường Dời được bao la non xanh nhưng khi bên anh Em giống như lụa đào mỏng manh Đã lâu không ai cạnh bên Giờ mong c'),
('que em mua nuoc lu|phuong my chi', 'Không còn con sông, nước dâng tràn lên bãi bờ Anh về quê em, khắp nơi như là biển khơi Chập chờn máy tranh ngoi lên giữa ngọn triều dâng Những đàn gà con bơ vơ đứng nhìn trời xanh '),
('thien duong voi nguoi thuong|phuong my chi', 'Hỡi ơi, người ơi, em không cần tìm kiếm đâu xa Vì em biết là anh thương em nhất mà Hỡi ơi, người ơi, ta đâu cần đi đâu nữa đâu Cõi thiên đường là ngồi đáy giếng với người mình thươ'),
('buon trang|phuong my chi', 'Trăng ơi Đừng đi mãi theo một người Trăng ơi Ngồi đây uống ly rượu mời Nghiêng nghiêng say say đêm nay Ta mời ngươi tới chơi Đêm ơi Còn thêm mấy đêm cuộc đời Trăm năm Mộng thi sĩ c'),
('sai gon hom nay mua|hoang duyen', 'Từ lâu ta chẳng cho nhau một câu hỏi chào Ngày ngày em nhắn cho anh "Dạo này anh thế nào?" Vài dòng tin nhắn đã lâu chẳng hồi đáp lại Chờ anh đến mắt ướt nhòe Mà sao anh im lặng đế'),
('mua hong|hoang duyen', 'Trời ươm nắng cho mây hồng Mây qua mau em nghiêng sầu Còn mưa xuống như hôm nào em đến thăm Mây âm thầm mang gió lên Người ngồi đó trong mưa nguồn Ôi yêu thương, nghe đã buồn Ngoài'),
('sai gon dau long qua|hoang duyen', 'Cầm tấm vé trên tay Em bay đến nơi xa Sài Gòn đau lòng quá Toàn kỷ niệm chúng ta Phải đi xa đến đâu? Thời gian quên mất bao lâu? Để trái tim em bình yên như ngày đầu tiên Mình đã t'),
('cho em mot lan yeu|hoang duyen', '(Nemo beautiful, love) Người bỗng đến bên em vào một hôm nắng xanh ngời Và rồi tay nắm tay như từng quen muôn kiếp trước Người nói, nói với em bao lời êm ái trên đời Và rồi như giấ'),
('em chi la|hoang duyen', 'Giây phút ta nhìn nhau mỉm cười Giây phút xinh đẹp nhất trên đời dừng lại ngay lúc ta chạm khẽ lên môi Xin thời gian ngừng trôi để ta mãi Giữ vẹn nguyên từng giây này cho đến sau n'),
('mua dam tham lau|hoang duyen', 'Anh chẳng biết được đâu Em đã thương anh từ lâu thật lâu Chỉ vì tính em khó nên chẳng thể nói được câu "Em yêu anh!" "Em thương anh, này anh có biết không?" Không cần nói nhiều đâu'),
('dieu buon nhat|hoang duyen', 'Thời gian trôi từng sáng tối Sao quá vội vẫn luôn là mình em thôi Nhìn theo anh tim tan vỡ Gần bên anh mãi là một giấc mơ Biết yêu riêng ai là rất buồn Biết yêu đơn phương là sẽ lu'),
('khach khong moi|hoang duyen', 'Vào năm mười sáu tôi đã gặp cậu Chàng trai có đôi mắt nâu Người giấu sâu bao tâm sự Đằng sau ánh mắt u sầu Lần đầu chạm tay nhau trái tim tôi đã rung động Hình như tôi đã biết yêu '),
('ngoc|nguyen thac bao ngoc', 'Huh Có rất nhiều những câu chuyện Em giấu riêng mình em biết Cũng bởi vì hạnh phúc của mình Muốn gìn giữ nên em lặng im Có những lần anh dối em Em vẫn nhớ những lần như thế Quá yêu'),
('buoc qua doi nhau|nguyen thac bao ngoc', 'Mình bước qua đời nhau để làm nhau đau Để làm nhau khóc gặp nhau không muốn chào Mình bước qua đời nhau để lại thương đau Để lại vết sầu có xoá mờ được đâu Mình đã từng hạnh phúc p'),
('hoi tham nhau|nguyen thac bao ngoc', 'Uh ah Chiều nay nhìn anh bước vội Không biết cuộc sống anh dạo này thế nào rồi Em vẫn như thế thôi vẫn cô đơn sớm tối Nhiều lúc bối rối con tim em lạc lối Khi em yêu thương anh hết'),
('ket thuc lau roi|nguyen thac bao ngoc', 'Uh heh uh ah Ngồi một mình nghĩ về cuộc tình đã tan vỡ Rồi thầm mơ thời gian có thể quay trở lại Để được cầm tay để được anh ôm vào lòng Hôn nhẹ lên bờ môi ấm áp đến vô cùng Giờ th'),
('co sao gio lai chia xa|nguyen thac bao ngoc', 'Lần mà người bối rối nói rằng yêu em thôi Cũng là lần đầu mà em thấy mình nhỏ bé Lần mà người đã đứng chờ em dưới cơn mưa đêm Làm tim em rung lên tưởng rằng anh sẽ mãi yêu em Mình '),
('yeu nham nguoi|nguyen thac bao ngoc', 'Hah hah Tình yêu đến với em quá vội vàng Rồi ra đi trong phút chốc bàng hoàng Giọt nước mắt em đã rơi rơi rất nhiều Anh cứ đi đi giờ em đã hiểu Giờ níu kéo chúng ta cũng chẳng là g'),
('mat anh roi|nguyen thac bao ngoc', 'Lần nào cũng thế, xót xa ê chề Mất, mất anh rồi em sống ra sao? Mất anh rồi em sống thế nào? Những yêu thương chẳng còn xuyến xao Nỗi đau này như ngàn vết dao Ai, ai sẽ cùng em đến'),
('tra cho anh|nguyen thac bao ngoc', 'Há ha ha hà ha ha há há há ha Há ha ha hà ha ha há há há há Ha ha hà ha ha Hu ha hà ha há ha hà hà hà Mai ta xa rời nhau gói gém kí ức buồn đau Bao yêu thương đậm sâu đến nay cũng '),
('vo kich cua em x anh voi quen x ly do la gi|nguyen thac bao ngoc', 'Nước mắt của anh thật sâu vào đáy Lòng để em biết tình yêu của em chỉ là đồ vui Và em chỉ là nhân vật kia ở trong vở kịch Em đã viết nên từ lần đầu gặp nhau Ta đã từng chung đêm sư'),
('tinh yeu den sau|myra', 'Gió đưa làn mây nhẹ trôi về đây Thoáng nghe mùi hương thật quen thật nhớ Chính anh tình yêu mà em mộng mơ Có nhau ngày sau là điều em ước ao Giấc mơ nhỏ nhoi được yêu người thôi Vẫ'),
('anh chua thuong em den vay dau|myra', 'Em đi xem phim một mình giữa đêm Và đi karaoke một mình giữa đêm Để biết em cô đơn làm sao Để biết em nhớ anh nhường nào Em đi Seoul một mình ngắm tuyết rơi Và đi Bali một mình ngắ'),
('giua dem bat khoc|myra', 'Ôi! Buồn quá, khoảnh khắc tâm tư cô đơn một chiều vội vã Ôi! Chờ mong, có biết anh đang nơi đâu vui hay buồn không? Và ngỡ là mơ, mà sau khi tan vỡ, tràn trề nhung nhớ Ôi! Làm ơn, '),
('dung yeu|myra', 'Ở phía cuối con đường có anh chỉ là giấc mơ Tại sao chỉ có một bước nữa em lạc mất anh Những dòng tin em nhắn cho anh cứ thế đi không hồi âm Rồi gặp nhau anh cười rạng rỡ tình cảm '),
('nhu nhung phut ban dau|myra', 'Nếu nuối tiếc tan trong bao tiếc nuối để yêu thương xa thật xa Nếu nỗi nhớ tan trong quên buốt giá và thời gian sẽ qua Cố giữ lấy dù chỉ là nước mắt để ngày mai được khóc dẫu muộn '),
('thuong nguoi thuong nguoi khac|myra', 'Bụi mưa lất phất chạm vào nước mắt vỡ trong hoàng hôn Người mà em thương đã coi một người là tất cả Ở tận cùng thế giới, cuối chân trời Em sẽ đợi anh suốt đời Bao giờ thì anh tới? '),
('anh chua thuong em den vay dau & nhu nhung phut ban dau|myra', 'Nếu nuối tiếc tan trong bao tiếc nuối để yêu thương xa thật xa Nếu nỗi nhớ tan trong quên buốt giá và thời gian sẽ qua Cố giữ lấy dù chỉ là nước mắt để ngày mai được khóc dẫu muộn '),
('duoi anh den san khau|myra', 'Khi ánh đèn sân khấu tắt đi Tôi lại về, tôi trong suy nghĩ Mọi thứ đã qua, tôi chờ mọi thứ đã qua Thời gian nào đâu dễ xoá Tôi ước mình là một khúc ca Thăng trầm tựa buồn vui câu h'),
('dung nhac ten em|myra', 'Đừng trao em giọt nước mắt cá sấu đi Vì anh đâu phải cá sấu Một phút mặc niệm trước khi em bước đi Vì em đâu phải người xấu ah oh Người ta nói anh nắm tay người khác Đi bên người k'),
('mashup co nguoi|myra', 'Chiều nay có người hẹn em với nụ cười tươi Chiều nay có người dạy anh cách làm mặt vui Dường như anh cũng đã quen rồi, ngày và đêm chỉ công việc thôi Người chợt đến như ánh Mặt Trờ'),
('con duong xua em di|nhu quynh', 'Con đường xưa em đi Vàng lên mái tóc thề Ngõ hồn dâng tái tê Anh làm thơ vu quy Khách qua đường lắng nghe Chuyện tình ta đã ghi Những mùa trăng vu quy Vì mưa gió không về Chiến trư'),
('nhu vat nang|nhu quynh', 'Ngồi quán uống ly cà phê Nghe nắng mưa đi về, em nhớ Chuyện dĩ vãng xưa ngày xưa Khi trái tim chung tình, hết rồi Mây trôi mãi lênh đênh Cuối trời xa vời Cây khô mãi bơ vơ Đứng chờ'),
('nho anh|nhu quynh', 'Nhớ ngày xưa đưa nhau qua đường phố quen Ánh bình minh xôn xao nhuộm đầy áo em Mặt trời đi theo ta đùa vui Bàn tay em nghiêng che nắng hồng Mặt trời đậu trên những ngón tay Nhớ chi'),
('goi ve anh|nhu quynh', 'Gởi về anh, một lá thư em viết bên đèn khuya Thời gian len lén đi mãi không ngừng, đêm tối mơ hồ Ngày anh đi mang theo vạn niềm nhớ Mang biết bao ân tình, nhìn anh thấy giận hờn Cỏ'),
('anh cu hen|nhu quynh', 'Anh cứ hẹn nhưng anh đừng đến nhé Để một mình em dạo phố lang thang Quán vắng quanh đây nụ hôn quá nồng nàn Em bước vội để che hồn trống vắng Anh cứ hẹn nhưng anh đừng đến nhé Để t'),
('mo anh trang ve|nhu quynh', 'Lặng thầm buồn, bên vầng trăng Chợt nhớ người, mắt lệ nhòa Em khóc than trong trời mùa đông Ôi người yêu giờ biết em đây đợi mong?? Tháng năm trôi, mấy đông rồi?? Một mình ngồi trá'),
('tam su voi anh|nhu quynh', 'Anh vô tình, anh chẳng hiểu cho em trong những đêm sầu vương Giờ trách anh đâu phải để bắt đền nhưng tại vì em buồn Vì hai đứa ta hai cuộc đời như một Chung một niềm sầu từ lứa tuổ'),
('anh buon em thuong|nhu quynh', 'Nhớ nhớ đôi mình khi vừa mới quen Em thẹn thùng trông ánh mắt mơ huyền Anh thầm nhìn em ước muốn làm quen Sao em quay mặt để anh buồn lắm Nhớ nhớ đôi mình khi tình mới trao Em thẹn'),
('cho anh ben doi|nhu quynh', 'Anh ơi! Ngày gặp gỡ bên dãy đồi Rồi tình thắm qua làn môi Vương vấn bao ngày trôi Thương nhớ bao giờ nguôi Qua những chiều Đông Hương ngát tình nồng Bên dãy đồi thông Mộng vàng chu'),
('tu do em buon|nhu quynh', 'Từ biệt nhau đi giữa mùa trăng xẻ đôi, lúc tình mới thành lời Trông nhau lần cuối, nước mắt tuôn mặn môi, nước mắt chia đôi đời Bóng anh khuất sau đồi, lúc mây tím giăng trời Lúc g'),
('nua doi yeu em|nhu quynh', 'Đường lên dốc cao là đường nhiều gian khổ Tình càng xót xa là tình khó phôi pha Đêm nay bên em dựa gió đời lạnh buốt Manh áo tuy dày mà nhịp tim run run Đền cao thánh tâm chúng con'),
('loi ca ru em|nhu quynh', 'Hát nữa đi anh khúc nhạc buồn Cho em nhớ lại tuổi yêu đương Thuở ta còn non dại mơ mộng Thuở đó bây giờ cứ vấn vương Hát nữa đi anh khúc nhạc tình Cho em nhớ lại tuổi còn xinh Một '),
('em mai con tinh dau|nhu quynh', 'Mùa xuân sang rồi em, mai nở vàng đầy cành Anh thấy buồn một mình Lưng trời bầy chim én, tung cánh bay triền miên Người yêu chờ không đến Mùa xuân xưa mùa xuân, hai đứa ngồi thật g'),
('em van hoai yeu anh|nhu quynh', 'Ai có hỏi vì đâu ta cách xa nhau rồi biết làm sao em nói đây Không trách là tại anh mang ước mơ xa vời nên tình mình nay dở dang Bao tháng ngày bên nhau em ngỡ tình muôn đời có ai '),
('buon lam chi em oi|nhu quynh', 'Buồn làm chi em ơi Lá xanh rồi cũng phai màu Ngỡ duyên mình bền lâu Ai ngờ lại xa cách nhau Trăng treo trên mái đầu Tâm tư nên âu sầu Qua bao nhiêu dãi dầu Mà lại nỡ qua cầu sang n'),
('anh tien tuyen, em hau phuong|nhu quynh', 'Em hậu phương còn anh nơi tiền tuyến Chúng ta cách xa rồi nhưng tình đâu có chia phôi Mình gọi tên nhau nhớ nhau trong mộng thôi Tha thiết yêu nhau mà vui Em hậu phương còn anh nơi'),
('thuo ay yeu nhau|nhu quynh', 'Thuở ấy yêu nhau anh làm thơ Thuở ấy yêu nhau em đợi chờ Dòng nước Hương Giang trôi lặng lờ Chưa biết chi giận hờn Và chưa biết sầu mộng mơ Thuở ấy yêu nhau mình lặng yên Chẳng nói'),
('nguoi phu tinh|nhu quynh', 'Thức trọn đêm trường Ngoài trời mưa mãi như vui lập cuộc đời Cố như lòng quên Càng ray rứt them hoài niệm anh với em Đường tình đơn phương đi hoài vào ngõ tối Người tình tôi thương'),
('tinh trang|nhu quynh', 'Em đẹp tên gọi Hằng Nga Tôi như chú cuội bên nhành cây đa Đêm đêm bên ánh trăng ngà Mơ nghe em hát mơ câu nghê thường Dây tình tôi trộm thầm vương Em xinh em đẹp ngọc ngà kiêu sa L'),
('huong tinh muon|nhu quynh', 'Sương ướt nhẹ bờ vai, lành lạnh gió thu về Gót buồn qua lối cũ, sao hồn nghe nhớ ai Nhớ ngày ta quen nhau, chua xót tình yêu muộn Nhìn nhau xa tầm tay, ôi âm thầm đắng cay Vừa bên '),
('chuyen tinh hoa trang|nhu quynh', 'Lâu quá không về thăm xóm đạo Từ ngày binh lửa cháy quê hương Khói bom che lấp chân trời cũ Che cả người thương nóc giáo đường Từ lúc giặc tràn qua xóm đạo Anh làm chiến sĩ giữ quê'),
('chuyen tinh la lan|nhu quynh', 'Tôi xin kể ra nơi đây Chuyện một người sơn nữ đẹp Đẹp như đóa hoa lan rừng Hương sắc ôi mặn nồng Nàng mang tên là La Lan La Lan người xứ cô mang Chưa yêu đương, chưa đau thương Nên'),
('noi lai tinh xua|nhu quynh', 'Về đây bên nhau, ta nối lại tình xưa Chuyện tình mà bao năm qua, em gói ghém từng kỷ niệm Phai nắng con đường xưa, những chiều hẹn nhau mưa đổ Mưa ướt lạnh vai anh, em thấy lòng mì'),
('cho nguoi|nhu quynh', 'Một người con gái đứng nghiêng nghiêng vành nón lá Đường chiều bờ đê lối xưa kỷ niệm thiết tha Lòng nàng sao lưu luyến quá Hẹn hò một người đi xa, mà năm tháng đã dần qua Chuyện tì'),
('nguoi ngoai pho|nhu quynh', 'Người đi đi ngoài phố, chiều nắng tắt bên sông Người đi đi ngoài phố, bóng dáng xưa mịt mù Thành ghế đá chiều công viên Ngày xưa, ngày xưa, ngày xưa đã hết rồi Người đi đi ngoài ph'),
('xin nguoi ve|nhu quynh', 'Bao năm em đợi chờ Mong tin ai tóc ngã bạc màu Xin người về để tình mình đẹp mãi dài lâu Ðêm đêm em nguyện cầu Xin ơn trên ban phép nhiệm màu Cho người về để tình mình mãi mãi gần '),
('nho|nhu quynh', 'Đêm qua Phạm Thái nhớ Quỳnh Như Thuyền dạt xa khơi nhớ bến bờ Chiêm nữ bâng khuâng ngồi nhớ bạn Ngũ Hành Sơn có nhớ Tây Du Trọng Thủy lên đường nhớ Mỵ Châu Ngưu Lang Chức Nữ nhớ nh'),
('nho nhau hoai|nhu quynh', 'Em ở nơi nào Có còn mùa xuân không em Rừng ngàn lá gió Từng đêm nhắc nhở thì thầm Nắng ở trên đầu, nắng trong lòng phố Gió ở trên non, gió cuốn mây về Sao anh vẫn ngồi mà nghe cô đ'),
('nguoi thuong ke nho|nhu quynh', 'Em đi rồi một mình tôi ở lại đêm bỗng dài nghe lạnh đầy bờ vai người đi mang nỗi nhớ người ở lại mang nỗi chờ Cuộc đời bỗng bơ vơ chỉ còn lại vần thơ em đi rồi nửa hồn tôi khờ dại '),
('mua|nhu quynh', 'Mưa mưa vẫn rơi như muôn đời Là những giọt nước cứ rơi rơi Mưa không biết khi xưa mưa về Cùng não nề lê bước đêm khuya Mưa mưa tầm tã xuống đời nhau vội vã Còn biết tìm đâu những n'),
('mua rung|nhu quynh', 'Mưa rừng ơi! Mưa rừng Hạt mưa nhớ ai mưa triền miên. Phải chăng mưa buồn vì tình đời Mưa sầu vì lòng người Duyên kiếp không lâu Mưa từ đâu mưa về? Làm muôn lá hoa rơi tả tơi Tiếng '),
('mua chieu|nhu quynh', 'Mây vương vài cơn gió reo buồn Hạt mưa rớt bên đường Chiều dâng bao niềm thương Quanh co đường đi vắng tiêu điều Dừng nếp sống mến yêu Mưa rơi thêm đìu hiu Ai ngân đàn trong tiếng '),
('lien khuc mua|nhu quynh', 'Trời đã khuya rồi đấy Trăng chênh chếch xuyên ánh qua mành Trời đã khuya rồi đấy Mưa trên xóm xa ánh đô thành Người anh tôi không quen ơi! Mưa rừng về ngập trời Mưa làm chi cho ướt'),
('mua tren bien vang|nhu quynh', 'Mưa buồn mãi rơi trên biển xưa âm thầm Ôi biển vắng đêm nao tình trao êm đềm Cơn sóng nào khơi lên nỗi đau trong em bao nhiêu chiều Lang thang một mình Anh giờ đã như mây dạt trôi '),
('mua xuan dau tien|nhu quynh', 'Bao nhiêu thương nhớ gom nhặt đầy anh trở về thăm em Bao lần ngồi thâu đêm nghe mùa xuân vừa đến Em ơi hoa thắm rơi ngập đường trời nắng xế vương vương Lòng nhớ tới em luôn khi chi'),
('hue buon|nhu quynh', 'Anh đi rồi xứ Huế buồn hiu đó anh Chim xa đàn không còn nghe hót trên cành Em của anh cũng sầu mênh mông Khi vắng anh đứng nhìn bên sông Nỗi u hoài xé nát buồng tim bé bỏng Mưa trê'),
('ngoai o buon|nhu quynh', 'Từ tiền tuyến tôi về thăm căn nhà ngoại ô, thấy lòng thương vô bờ Cũng con đường này đây, cũng mái nhà này đây, còn mang kỷ niệm đầy Nhưng trăng đêm nay không còn tha thiết như nhữ'),
('vong co buon|nhu quynh', 'Đêm dài nghe tiếng vọng cổ buồn Nức nở vầng trăng khuya cung đàn buông tiếng khóc Tiếng gõ nhịp song lang ai oán khúc tơ lòng Như tiếng lòng chim quyên đang đón gió thu về Anh giờ '),
('hen ho dem trang|nhu quynh', 'Đêm nay trời sáng trăng mình bên nhau cùng hoà chung câu hát Hương xuân tình đắm say nhạc lâng lâng lòng em nghe sao xuyến Ta say cùng ánh trăng cùng muôn sao lấp lánh trên trời ca'),
('vong gac dem suong|nhu quynh', 'Buông khói gây thưa Tôi kể người nghe một chuyện tâm tình Nửa đêm giá lạnh Bỗng nghe ấm một tình thương trong tim Sương rớt trên vai Qua ngõ hồn trai vào lòng đêm dài Gác súng biên'),
('ke chuyen trong dem|nhu quynh', 'Một đêm biết chuyện chúng mình yêu nhau Người bạn chiến đấu nằm bên nói rằng Xin chúc hai người suốt đời yêu nhau Như trái cau xanh chung tình cùng trầu Tình yêu như hoa sóng trên '),
('mua dem ngoai o|nhu quynh', 'Trời đã khuya rồi đấy Trăng chênh chếch xuyên ánh qua mành Trời đã mưa rồi đấy Mưa trên xóm xa ánh đô thành Đường ngoài kia không xôn xao Không đẹp vì đèn màu Ôi đường dài hun hút '),
('ngay vui hai dua|nhu quynh', 'Một chiều xưa, phương xa anh mới đến Lần đầu tiên quê em anh quyến luyến Ngoài vườn hoa anh đứng bên cành lá Hôm ấy anh gặp em Gặp được em anh mới xin làm quen Một lời trao xin kết'),
('goi ten ngay moi|nhu quynh', 'Một nụ hồng trên tay cuộc đời đẹp biết mấy. Lúc cô đơn đâu hay trong ta tình đầy Và nụ hồng trao đi người mỉm cười đôi khi. Những ưu tư lâu nay cũng qua. Người đâu biết tình đắng, '),
('mot ngay khong goi nhau|nhu quynh', 'Đã qua một ngày không gọi nhau Anh tự hỏi lòng mình có nhớ Nhớ mắt em ngoan, nhớ nụ cười hiền Đường tuy xa sao thấy cứ như gần Đã thêm một ngày không gọi nhau Tay nhẹ buông từng ng'),
('mot ngay khong goi ten nhau|nhu quynh', 'Đã qua một ngày không gọi nhau Anh tự hỏi lòng mình có nhớ Nhớ mắt em ngoan, nhớ nụ cười hiền Đường tuy xa sao thấy cứ như gần Đã thêm một ngày không gọi nhau Tay nhẹ buông từng ng'),
('tam anh ngay xua|nhu quynh', 'Ngày nao em đến chơi tặng tôi một chiếc hình Ghi nhớ ngày chúng mình vừa quen nhau Năm tháng dài ngày sau ghi nhớ mãi Hình em tóc ngang vai lược giắt với hoa cài Nét mi cong viền k'),
('lk noi buon hoa phuong & luu but ngay xanh|nhu quynh', 'Mỗi năm đến hè lòng man mác buồn Chín mươi ngày qua chứa chan tình thương Ngày mai xa cách hai đứa hai nơi Phút gần gũi nhau mất rồi Tạ từ là hết người ơi Tiếng ve nức nở buồn hơn '),
('ngay tet que em|nhu quynh', 'Tết, Tết, Tết, Tết đến rồi Tết, Tết, Tết, Tết đến rồi Tết, Tết, Tết, Tết đến rồi Tết đến trong tim mọi người Mừng ngày Tết trên khắp quê tôi Ngàn hoa thơm khoe sắc xinh tươi Đàn em'),
('khong gio roi|nhu quynh', 'Không giờ rồi em ngủ đi thôi Hơi đâu mà lo lắng em ơi Thà nghèo mà biết mến thương nhau Còn hơn giàu có đổi thay mau Chẳng lẽ nghèo hoài hay sao? Không giờ rồi anh biết chưa anh Sa'),
('loai hoa khong vo|nhu quynh', 'Một loài hoa không vỡ, đó là loài hoa nở trong vườn yêu Một loài hoa sớm nở Nhưng không chóng già, đời hoa vẫn mặn mà Dù mưa gió nhiều làm cánh hoa lay Nhưng rồi, lặng gió mưa bay '),
('neu doi khong co anh|nhu quynh', 'Ra phố hôm nay thấy buồn lên mắt Đường chiều man mác như gợi niềm thương Chờ người yêu đến cùng chung ngõ hồn Với vòng tay xanh đón mời cho đời lên ngôi thần thánh Đôi mắt em say g'),
('khong phai tai chung minh|nhu quynh', 'Không phải tại em cũng không phải tại anh Tại Trời xui khiến nên chúng mình thương nhau Tình nồng thắm biết bao lúc ông Tơ bắc cầu Bà Nguyệt nối chữ yêu vui trọn buổi ban đầu Rồi t'),
('trai tim khong ngu yen|nhu quynh', 'Nếu anh nói anh vẫn chưa yêu Là thật ra anh đang dối mình Còn anh nói trót đã yêu em rồi Là hình như anh đang dối em Nếu anh nói anh vẫn chưa yêu Là thật ra anh đang dối mình Còn a'),
('khong bao gio quen anh|nhu quynh', 'Tôi viết lên đây với tất cả chân thành của lòng tôi trao anh. Ngày nao đã quen nhau vì chung hướng đời mình trót trao nhau nụ cười. Và tình yêu đó tôi đem ép trong tim, Dù bụi thời'),
('neu mot ngay|dan nguyen', 'Nếu nếu một ngày không có em Thì niềm cô đơn dài như năm tháng Như mùa thu chết như lá khô rơi Nếu nếu ngày ấy mình đừng quen nhau Thì ngày nay có đâu buồn đau Những khi mình xa nh'),
('xin lam nguoi xa la|dan nguyen', 'Còn gì đâu em tháng ngày vui qua mất rồi Còn gì đâu em thôi đừng đến đắng cay thêm Ðoạn buồn ta đi còn dài lê thê Bởi còn đam mê xuôi bước chân quên về Nên nhớ quên câu thề Từ đó đ'),
('linh hon tuong da|dan nguyen', 'Trên dốc đá tôi tình cờ quen nàng Ngồi bên nhau, gọi tên nhau để rồi xa nhau Em đã đến và đã đến như áng mây Như cánh chim bay qua bầu trời Ôi hình hài một vài giờ vui Tôi muốn nói'),
('khong con nho nguoi yeu|dan nguyen', 'Tôi không còn thương nhớ người yêu Từ em cô dâu sính lễ qua cầu Nỡ quên kỷ niệm ngày thơ ấu Trò chơi cưới hỏi đầy yêu dấu Tôi chú rể, em làm cô dâu Tôi không còn thương nhớ người t'),
('sai gon ky niem|dan nguyen', 'Sài Gòn yêu ơi, đã hết rồi ngày tháng đam mê Nhớ đường xưa mình vẫn đi về Nhớ từng viên sỏi đá bên lề Tiếng vọng buồn mưa gió đêm khuya Như dòng lệ chinh chiến chia ly Sài Gòn yêu '),
('tim vo|dan nguyen', 'Chiều hỡi, biết mây về đâu ở đâu? Hay mây còn đau nỗi đau hằn trong tim sầu? Mùa đông màn đêm buông mau Đàn chim một ngày gian lao Từng đôi líu lo lời thương yêu ngọt ngào Người hỡ'),
('anh yeu em vao coi chet|dan nguyen', 'Anh đã biết, anh đã biết yêu em là tuyệt vọng 나는 이미 알았어, 너를 사랑하는 건 절망이라는 걸 Mà vì sao, mà vì sao anh vẫn cứ yêu thương? 그런데 왜, 그런데 왜 나는 여전히 사랑할까? Con giun con nằm uốn khúc giữa đêm '),
('nho ve em|dan nguyen', 'Đêm đêm gió thổi từng cơn Gió lạnh về từng cơn Nhớ người em gái phương xa Đêm đêm anh ngắm sao trời Thấy lòng nhớ thương vô vàn người em gái Đêm nay nhớ nhiều về em Với kỉ niệm ngà'),
('ngay em di|dan nguyen', 'Ngày em ra đi Em chỉ mang con tim hành lý Để quên mùa đông Cho tháng năm anh thêm lạnh lùng Đôi tay hôm nào Dìu nhau trong cơn mê đầy Giờ đôi tay ấy Lau ngấn lệ ngàn đời biệt ly Ch'),
('nhan co cho em|dan nguyen', 'Anh nghèo không có nhẫn kim cương Anh chỉ tặng em nhẫn cỏ thường Nhẫn cỏ nghèo nàn em biết lắm Nhưng lòng kỷ niệm của yêu đương Anh nghèo nên chẳng nhẫn kim cương Tặng em theo sính'),
('mua xuan do co em|dan nguyen', 'Nếu chiều nay lỡ hẹn không về Thì xuân năm nay xuân sẽ buồn Sẽ buồn hơn mấy cội mai già Và mùa xuân quên mặc áo mới Hẹn hò xa xưa để quên tất cả Dành cho em tình yêu rất lạ Dù sao '),
('ao em chua mac mot lan|dan nguyen', 'Tôi với nàng hai đứa nguyện yêu nhau Tha thiết từ đây cho đến ngày bạc đầu Để giao ước tôi trao nàng nhẫn cưới Em cũng tặng tôi khăn hồng thêu cành hoa mai Tôi vốn nghèo, em cũng c'),
('lk: mot ngay khong co em, ngay vui qua mau|dan nguyen', 'Một ngày không có em Là lòng anh tan nát Cả trời mây u ám Thời gian vẫn âm thầm Âm thầm hằn trên bia đá xanh Một ngày không có em Là lòng anh se thắt Cả ngàn cây im tiếng Chịu tang'),
('tinh yeu cach tro|dan nguyen', 'Anh biết tại sao em luôn u buồn Và thường suy tư trong những chiều buông Em muốn xa anh phải không? Ôi đời ai hiểu tình yêu Mới yêu thì hứa một lòng Anh biết tại sao em anh hay buồ'),
('lai nho nguoi yeu|dan nguyen', 'Vì sao anh nhớ em thế này? Thương nhớ đong đầy trong lòng mắt Buổi chiều còn gặp nhau đây Mà đêm đã nhớ như vầy Em hỡi em có hiểu có hay? Tình anh như núi cao biển rộng Gom bốn phư'),
('tinh nhat phai|dan nguyen', 'Chiều buồn nghiêng nắng Biển vắng mênh mông lang thang mình ta Mây trên cao bay khuất chân trời Và theo gió cuốn trôi đi bao nhiêu mộng mơ Ngày nào mình tình cờ quen nhau Và đến bê'),
('muoi nam tinh cu|dan nguyen', 'Mười năm không gặp tưởng tình đã cũ Mây bay bao năm tưởng mình đã quên Như mưa bay đi một trời thương nhớ Em ơi bên kia có còn mắt buồn? Mười năm cách biệt, một lần bỡ ngỡ Quên đi,'),
('dem buon tinh le|dan nguyen', 'Ðã lâu rồi đôi lứa cách đôi nơi Tơ duyên xưa còn hay mất Mái trường ơi em tôi còn học nữa Hay ra đi từ độ nào Ngày xưa đó ta hay đón dìu nhau Đi trên con đường lẻ loi Mấy năm qua r'),
('chap tay lay nguoi|dan nguyen', 'Tôi chắp tay xin lạy, tôi lạy người đời Lạy bạn bè, lạy em đã lừa dối Tôi xin lạy cơn đau Đi trên vực sâu nghe buồn gì đâu Khi chưa tỏ tình đã nói xa nhau Tôi chắp tay xin lạy đêm '),
('doan buon dem mua|dan nguyen', 'Đêm nay trên phố mưa tơi bời Lòng nghe bao nhớ nhung đầy vơi Làm sao cho em vui Còn ai cho em vui Bằng môi trên đôi môi ôi tuyệt vời Đêm nay anh biết em thương nhiều Buồn tênh trên'),
('pho dem|dan nguyen', 'Phố đêm đèn mờ giăng giăng Màu trắng như vì sao gối đầu ngủ yên Phố đêm nhiều lần suy tư Ghi nhớ còn trong đời Những ngày thương tích lớn Mây đen làm úa trăng gầy Cho nên còn tiếng'),
('dem tam su|dan nguyen', 'Mình gặp nhau như lúc Mới quen ban đầu cớ sao anh ngập ngừng Nhà tôi đơn côi mời em ở lại Kể chuyện tha hương chưa lần phai nhớ thương Mang tâm sự từ thuở Thiếu đôi tay mềm biết nơ'),
('ta ao dem noel|dan nguyen', 'Tiền đồn biên giới heo hút trong màn tối Vài đốm hỏa châu lẻ loi soi cuối trời Chầm chậm chuông ngân đánh nghe buồn tênh Ánh sao hiền lấp lánh báo tin lành chúa sinh Kỷ niệm năm ấy'),
('hay ve day ben anh|quang le', 'Em yêu Em có biết anh nhớ em nhiều lắm Ngày tháng trôi qua anh vẫn mong, vẫn chờ Giờ em đang ở đâu? Em có còn yêu anh nữa không? Mà sao không thấy một lời cho nhau? Một mùa thu tàn'),
('sao anh no danh quen|quang le', 'Sao anh nỡ đành quên bao lời tha thiết mong chờ Sao anh nỡ đành quên chuyện tình đẹp như ước mơ Sao anh nỡ đành quên áng mây chiều nghiêng nghiêng bóng Những con đường quen lối đi '),
('gui ve em|quang le', 'Gửi về em một lá thư anh viết bên đèn khuya Thời gian len lén đi mãi không ngừng, đêm tối mơ hồ Ngày anh đi mang theo vạn niềm nhớ, mang biết bao ân tình Nhìn em thấy giận hờn, cỏ '),
('em hay ve di|quang le', 'Thôi em hãy về đi Xin trả lại em, những gì đầu môi em trao Xui hai đứa gặp nhau mai sau nên nghĩa vợ chồng Mà nay đâu ngờ biệt ly, em chớ buồn mà chi Thôi em hãy về đi Em chớ sầu b'),
('nguoi em vy da|quang le', 'Tôi nhớ người em Vỹ Dạ Gặp bên chợ Đông Ba Lần ghé miền Trung yêu thương Theo chuyến đò xuôi ngược dòng Hương Nón lá che khuất mắt biếc ớ Cặp sách sớm trưa chiều Đi học Đồng Khánh '),
('nho ve em|quang le', 'Đêm đêm gió thổi từng cơn Gió lạnh về từng cơn Nhớ người em gái phương xa Đêm đêm anh ngắm sao trời Thấy lòng nhớ thương vô vàn Người em gái Đêm nay nhớ nhiều về em Với kỷ niệm ngà'),
('bai ca tet cho em|quang le', 'Tết này anh không thèm kẹo mứt Vì đã có môi em thơm ngọt tựa sen hồng Tết này anh không thèm đi chơi Xi-nê hay nhạc hội, Đà Lạt hay Vũng Tàu Vì đã có em đem lại mộng đời Tô thêm và'),
('tinh em bien rong song dai|quang le', 'Hòa bình ơi Tình yêu em như sông biển rộng Tình yêu em như lúa ngoài đồng Tình yêu em tát cạn biển Đông Hòa bình ơi, ơi hòa bình ơi Sao em nỡ lòng kẻ đợi người trông Sao em nỡ lòng'),
('xin em dung khoc vu quy|quang le', 'Đừng nhìn nhau chi mà hoen lệ bờ mi Tình dù chưa phai không tránh được từ ly Ai biết đời mai sau bao giờ ai biết đâu ngờ Tình hai chúng ta lẽ nào phôi pha Xót xa từng kỷ niệm đầy v'),
('yeu mot minh|quang le', 'Nhà em có hoa vàng trước ngõ Tường thật là cao, có dây leo kín rào Nhà anh cuối con đường ngoại ô Vách thưa đèn dầu thắp, gió lùa vào từng đêm Tuổi em cũng như hoa mới nở Vạn người'),
('nguoi yeu co don|quang le', 'Đời tôi cô đơn nên yêu ai cũng không duyên Đời tôi cô đơn nên yêu ai cũng không thành Đời tôi cô đơn nên yêu ai cũng dở dang Yêu ai cũng lỡ làng dù rằng tôi chẳng lỗi chi Đời tôi c'),
('lien khuc mua nua dem|quang le', 'Mưa Nửa Đêm Đêm chưa ngủ nghe ngoài trời đổ mưa Từng hạt rơi gác nhỏ đèn le lói bóng dáng in trên tường loang. Anh gối tay tôi để nghe chuyện xưa cũ gói trọn trong nổi nhớ. Tôi muố'),
('lien khuc mua nua dem & ai cho toi tinh yeu|quang le', 'Đêm chưa ngủ, nghe ngoài trời đổ mưa từng hạt rơi Gác nhỏ đèn le lói bóng dáng in trên tường loang Anh gối tay tôi để ôn chuyện xưa cũ Gói trọn trong tuổi nhớ Tôi muốn hỏi, có phải'),
('bien tinh|quang le', 'Nằm nghe sóng vỗ từng lớp xa Bọt tràn theo từng làn gió đưa Một vầng trăng sáng như tình yêu chúng ta Vượt ngàn hải lý cũng không xa Biển rộng đất trời chỉ có ta Thì dòng ngân hà m'),
('tinh nho mau quen|quang le', 'Ủa, anh Lê, anh mới về hả? À, em, em là... Út nè! Nhớ hông? Út Lượm, phải hông? Phải rồi! Trời ơi, dạo này em lớn bổn à nha Ủa, tự nhiên anh đi đâu mà lâu quá anh mới về thăm vậy? '),
('chuyen tinh song huong|quang le', 'Một sớm anh đi không lời giã từ Để cho Huế buồn, Huế giận nghìn thu Nghìn thu dòng tóc buông dỗi hờn Về nghe gió qua lòng lạnh từng cơn nhớ mong Ngày đó sông Hương chưa từng biết b'),
('chuyen tinh hoa muoi gio|quang le', 'Ngày xưa, em hay nói thích hoa mười giờ Nên anh hay tìm, tặng cho em những cánh hoa màu tím Em hay nói rằng hoa tím còn khoe sắc, ta còn yêu nhau Dẫu xa muôn trùng, mình đừng quên '),
('chuyen tinh khong di vang|quang le', 'Vàng cây lá bay, đôi tay ngây buồn mang suy tư về Đầy đôi mắt nhung, kiêu sa môi mềm tìm đến bên em Niềm tin đã lạnh theo tháng năm đã mang Em có nghe ngoài phố đang kết hoa Bao nh'),
('nguoi mang tam su|quang le', 'Sang sông mà lỡ chuyến đò Yêu đương một gánh bây giờ gãy đôi Từ ngày tình nghĩa chia phôi Em đi đường ấy bỏ tôi một mình Người ta dỗ ngọt tôi vào tình yêu Bây giờ chê chát nẻo đi đ'),
('doi mat nguoi xua|quang le', 'Chuyện tình của tôi tan vỡ từ lâu rồi Tưởng không bao giờ còn nhớ Nhưng bỗng một hôm trên đường ra phố thị Tôi gặp người yêu ngày nào Đôi mắt ưu tư thật buồn nàng nhìn tôi Rồi quay'),
('hoa tim nguoi xua|quang le', 'Rồi chiều nay lá khô rơi đầy có người nhìn buồn lây Gom nhớ thương sưởi tình cô liêu ấm thêm lòng ít nhiều Tâm tư bâng khuâng ngày đôi ta đến đây Cũng vườn xưa chốn này Hương xưa ơ'),
('nguoi phu keo mo cau|quang le', 'Trò chơi thuở bé, anh ưa kéo mo cau Chở em quanh ngõ vườn Cô bé mỹ miều, cười run run bờ vai Tay ôm chắc vành mo Chiếc tàu mo nhỏ bé, anh giả người phu xe Hỏi, "Đi đâu bé à?" Em tr'),
('tam su nguoi linh tre|quang le', 'Từ khi anh thôi học Từ khi đôi đứa đôi đời Từ sông ngăn, núi trở Tạ từ không nói nên lời Từ khi gót sông hồ ngược xuôi Ôi những đêm thật dài hồn nghe thương nhớ ai Một năm tìm vui '),
('o hai dau noi nho|quang le', 'Tơ duyên xưa còn hay mất Mái trường ơi em tôi còn học nữa Hay ra đi từ độ nào. Ngày xưa đó ta hay đón dìu nhau Đi trên con đường lẻ loi Mấy năm qua rồi em tôi không gặp nữa Bao yêu'),
('chuyen ba mua mua|quang le', 'Đời từ muôn thuở Tiếng mưa có vui bao giờ Chuyện lòng tôi kể Cách đây đã ba mùa mưa Tôi đem tất cả Chuyện lòng trao hết cho người Nguyện tròn thương tròn nhớ Nàng là trinh nữ Tóc b'),
('mua tren pho hue|quang le', 'Chiều nay mưa trên phố Huế Kiếp giang hồ không bến đợi Mà mưa rơi vẫn rơi, rơi hoài cho lòng nhớ ai Ngày chia tay hôm nao còn đây Nước trên sông Hương còn đầy Tình đã xa, gió mưa u'),
('dem bo vo|quang le', 'Đêm bơ vơ, thương ai đêm đợi đêm chờ Trời bây giờ, trời buồn nên trời hay mưa Từ buổi em đi, mang theo hoa buớm ngày xuân Từng giờ chia ly, khi nào em nhớ anh không? Đêm bơ vơ, thư'),
('hai chuyen tau dem|quang le', 'Lòng buồn dạt dào nhớ hôm nào xuôi miền Trung chuyến xe đêm anh gặp em Môi em đang xuân nhưng mắt buồn ngấn lệ trần Chuyện đời sầu đắng vấn vương đôi má dịu hiền Áo em màu tím Đậm '),
('dem trao ky niem|quang le', 'Còn đêm nay ta với mình đi vào tình yêu Để nhung nhớ đến trong muôn chiều Mai mốt này cuộc đời quạnh hiu Xa nhau xin nhớ ngày ban đầu xao xuyến Xin nhớ người mong chờ ưu phiền Xin '),
('chim sao ngay xua|quang le', 'Ngày xưa em như chim sáo Sống vô tư, hay mộng mơ nhiều Nhìn em đi qua cuối xóm Làn tóc mây bay, má ửng hồng Chiều nay theo em anh bước Bước bên em trên con đường làng Nhìn em, anh '),
('khong phai tai chung minh|quang le', 'Không phải tại anh cũng không phải tại em Tại Trời xui khiến nên chúng mình thương nhau Tình nồng thắm biết bao, lúc ông Tơ bắc cầu Bà Nguyệt nối chữ yêu, vui trọn buổi ban đầu Rồi'),
('xuan nay con khong ve|quang le', 'Con biết bây giờ mẹ chờ tin con Khi thấy mai, đào nở vàng bên nương Năm trước con hẹn đầu xuân sẽ về Nay én bay đầy trước ngõ mà tin con vẫn xa ngàn xa Ôi nhớ xuân nào thuở trời yê'),
('dem nay bo khong ve|manh quynh', '. Hãy ngủ đi [Em] con đêm nay bố chắc không [C] về Bệnh viện thật [Am] đông không đủ [D] người chăm lo trước [G] sau Bố nát [Bm] lòng khi đứng nhìn bệnh [C] nhân Đang quằn [A] quại'),
('sau loi tu khuoc|manh quynh', 'Chăn mền tôi đắp Vẫn còn vương vấn cũ Sau làn da thắm Vết thương chưa dứt đủ Thế nên mình đến lúc này Biết đâu là quá ngây dại? Những lời yêu dấu Thốt ra ru êm tôi Cung đàn anh tấu'),
('nhat|manh quynh', 'Ta từng là lẽ sống Ta từng là ánh sáng nơi nhau Nhưng điều luôn nói trước đây, cho rằng chuyện chẳng đổi thay Hôm nay nên xem lại Ta chạy theo ý nghĩ riêng Ta bận tâm những thứ xun'),
('huyen thoai|manh quynh', 'Chiếc nón lá che ngang hai đứa khô Tấm áo trắng thôi không bay nữa Hồi ức về em còn Hình bóng của em còn Hằng đêm Nuốt lấy bóng trăng giữa sương mù Phút chốc thấy ta giống như Nhẹ '),
('di de tro ve mashup|manh quynh', 'Sớm nay Sáng xuân tinh mơ vội vàng lên chuyến xe Chuyến xe đưa tôi trở về nhà với mẹ Lòng tôi đã xôn xao nôn nao từ tận tối qua Tôi như đứa trẻ Lời nghe xao xuyến và Rộn ràng trong'),
